CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE TABLE public.user_roles (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin','candidate')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.foundation_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') AND COALESCE(auth.jwt()->'app_metadata'->>'role','')='admin' $$;
REVOKE ALL ON FUNCTION public.foundation_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.foundation_admin() TO authenticated,service_role;
CREATE TABLE public.candidate_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id), display_name text, professional_summary text, interest_countries text[], interest_regions text[], availability_date date, language_levels jsonb NOT NULL DEFAULT '{}', work_authorization text CHECK(work_authorization IN ('authorized','not_authorized','unknown')), visa_status text, sponsorship_required boolean, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,owner_id));
GRANT SELECT,UPDATE ON public.candidate_profiles TO authenticated; GRANT ALL ON public.candidate_profiles TO service_role;
ALTER TABLE public.candidate_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY candidate_read ON public.candidate_profiles FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY candidate_update ON public.candidate_profiles FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.candidate_experiences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL DEFAULT auth.uid(), employer text, title text, country text, started_on date, ended_on date, description text, verified_at timestamptz, FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), CHECK(ended_on IS NULL OR started_on IS NULL OR ended_on>=started_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.candidate_experiences TO authenticated; GRANT ALL ON public.candidate_experiences TO service_role;
ALTER TABLE public.candidate_experiences ENABLE ROW LEVEL SECURITY;
CREATE POLICY experiences_own ON public.candidate_experiences TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX experiences_candidate ON public.candidate_experiences(candidate_id);
CREATE TABLE public.candidate_education (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL DEFAULT auth.uid(), institution text, qualification text, field_of_study text, started_on date, ended_on date, FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), CHECK(ended_on IS NULL OR started_on IS NULL OR ended_on>=started_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.candidate_education TO authenticated; GRANT ALL ON public.candidate_education TO service_role;
ALTER TABLE public.candidate_education ENABLE ROW LEVEL SECURITY;
CREATE POLICY education_own ON public.candidate_education TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX education_candidate ON public.candidate_education(candidate_id);
CREATE TABLE public.candidate_certifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL DEFAULT auth.uid(), name text, issuer text, issued_on date, expires_on date, FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), CHECK(expires_on IS NULL OR issued_on IS NULL OR expires_on>=issued_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.candidate_certifications TO authenticated; GRANT ALL ON public.candidate_certifications TO service_role;
ALTER TABLE public.candidate_certifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY certifications_own ON public.candidate_certifications TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX certifications_candidate ON public.candidate_certifications(candidate_id);
CREATE TABLE public.candidate_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL, storage_path text NOT NULL, file_name text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), version integer NOT NULL DEFAULT 1 CHECK(version>0), processing_state text NOT NULL DEFAULT 'pending' CHECK(processing_state IN ('pending','processing','ready','failed')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), UNIQUE(candidate_id,storage_path,version));
GRANT SELECT ON public.candidate_documents TO authenticated; GRANT ALL ON public.candidate_documents TO service_role;
ALTER TABLE public.candidate_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_own_read ON public.candidate_documents FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX documents_candidate ON public.candidate_documents(candidate_id);
CREATE TABLE public.job_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, base_url text NOT NULL UNIQUE, allowed boolean NOT NULL DEFAULT false, configuration jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.job_sources TO authenticated; GRANT ALL ON public.job_sources TO service_role;
ALTER TABLE public.job_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY sources_read ON public.job_sources FOR SELECT TO authenticated USING(allowed OR public.foundation_admin());
CREATE TABLE public.jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), source_id uuid REFERENCES public.job_sources(id), employer text NOT NULL, title text NOT NULL, original_url text, canonical_url text, dedup_key text NOT NULL, fingerprint text NOT NULL, country text, location text, description text, work_type text, pay_min numeric CHECK(pay_min>=0), pay_max numeric CHECK(pay_max>=pay_min), currency text, pay_period text CHECK(pay_period IN ('hour','day','week','month','year')), experience_years numeric CHECK(experience_years>=0), languages text[], housing boolean, visa_sponsorship boolean, international_eligible boolean, collected_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,dedup_key), UNIQUE(owner_id,fingerprint), UNIQUE(id,owner_id));
GRANT SELECT ON public.jobs TO authenticated; GRANT ALL ON public.jobs TO service_role;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY jobs_own_read ON public.jobs FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX jobs_source ON public.jobs(source_id);
CREATE INDEX jobs_country ON public.jobs(owner_id,country);
CREATE TABLE public.rule_sets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','testing','active','archived')), rules jsonb NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), UNIQUE(candidate_id,version), UNIQUE(id,candidate_id,owner_id));
GRANT SELECT ON public.rule_sets TO authenticated; GRANT ALL ON public.rule_sets TO service_role;
ALTER TABLE public.rule_sets ENABLE ROW LEVEL SECURITY;
CREATE POLICY rules_own_read ON public.rule_sets FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE UNIQUE INDEX one_active_rule_set ON public.rule_sets(candidate_id) WHERE status='active';
CREATE TABLE public.job_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL, job_id uuid NOT NULL, rule_set_id uuid NOT NULL, classification text NOT NULL CHECK(classification IN ('compatible','incompatible','pending_information')), score integer NOT NULL CHECK(score BETWEEN 0 AND 100), reasons jsonb NOT NULL CHECK(jsonb_typeof(reasons)='array'), missing_data jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(missing_data)='array'), evaluated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), FOREIGN KEY(job_id,owner_id) REFERENCES public.jobs(id,owner_id), FOREIGN KEY(rule_set_id,candidate_id,owner_id) REFERENCES public.rule_sets(id,candidate_id,owner_id), UNIQUE(candidate_id,job_id,rule_set_id));
GRANT SELECT ON public.job_evaluations TO authenticated; GRANT ALL ON public.job_evaluations TO service_role;
ALTER TABLE public.job_evaluations ENABLE ROW LEVEL SECURITY;
CREATE POLICY evaluations_own_read ON public.job_evaluations FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX evaluations_job ON public.job_evaluations(job_id);
CREATE INDEX evaluations_rules ON public.job_evaluations(rule_set_id);
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL, job_id uuid NOT NULL, status text NOT NULL DEFAULT 'discovered' CHECK(status IN ('discovered','selected','authorized','submitted','confirmed','uncertain','failed','withdrawn')), authorized_at timestamptz, authorized_by uuid REFERENCES public.profiles(id), authorization_note text, submitted_at timestamptz, confirmed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), FOREIGN KEY(job_id,owner_id) REFERENCES public.jobs(id,owner_id), UNIQUE(candidate_id,job_id), CHECK(status NOT IN ('authorized','submitted','confirmed','uncertain','failed') OR (authorized_at IS NOT NULL AND authorized_by=owner_id AND length(trim(authorization_note))>0)), CHECK(status NOT IN ('submitted','confirmed') OR submitted_at IS NOT NULL));
GRANT SELECT ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY applications_own_read ON public.applications FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX applications_job ON public.applications(job_id);
CREATE TABLE public.employer_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, owner_id uuid NOT NULL, job_id uuid, gmail_message_id text NOT NULL, gmail_thread_id text NOT NULL, sender text, subject text, received_at timestamptz, classification text NOT NULL DEFAULT 'other' CHECK(classification IN ('interview','rejection','info','other')), FOREIGN KEY(candidate_id,owner_id) REFERENCES public.candidate_profiles(id,owner_id), FOREIGN KEY(job_id,owner_id) REFERENCES public.jobs(id,owner_id), UNIQUE(candidate_id,gmail_message_id));
GRANT SELECT ON public.employer_messages TO authenticated; GRANT ALL ON public.employer_messages TO service_role;
ALTER TABLE public.employer_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_own_read ON public.employer_messages FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX messages_job ON public.employer_messages(job_id);
CREATE INDEX messages_thread ON public.employer_messages(candidate_id,gmail_thread_id);
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id), candidate_id uuid REFERENCES public.candidate_profiles(id), owner_id uuid NOT NULL REFERENCES public.profiles(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}', CHECK(metadata - ARRAY['status','version','classification','operation']::text[] = '{}'::jsonb));
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_own_read ON public.audit_events FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX audit_candidate_time ON public.audit_events(candidate_id,occurred_at DESC);
CREATE FUNCTION public.foundation_provision_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'candidate'); INSERT INTO public.candidate_profiles(owner_id) VALUES(NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.foundation_provision_account() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER foundation_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.foundation_provision_account();
CREATE FUNCTION public.foundation_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_events(actor_id,candidate_id,owner_id,action,entity_type,entity_id,metadata) VALUES(auth.uid(), CASE WHEN TG_TABLE_NAME='candidate_profiles' THEN NEW.id ELSE (to_jsonb(NEW)->>'candidate_id')::uuid END, NEW.owner_id, lower(TG_OP), TG_TABLE_NAME, NEW.id, jsonb_build_object('operation',TG_OP)); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.foundation_audit() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER audit_applications AFTER INSERT OR UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.foundation_audit();
CREATE TRIGGER audit_profiles AFTER UPDATE ON public.candidate_profiles FOR EACH ROW EXECUTE FUNCTION public.foundation_audit();
CREATE TRIGGER audit_rules AFTER INSERT OR UPDATE ON public.rule_sets FOR EACH ROW EXECUTE FUNCTION public.foundation_audit();
CREATE FUNCTION public.foundation_block_external_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status IN ('submitted','confirmed','uncertain','failed') THEN RAISE EXCEPTION 'External application actions remain disabled'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.foundation_block_external_status() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER applications_external_disabled BEFORE INSERT OR UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.foundation_block_external_status();
CREATE FUNCTION public.foundation_health() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('infrastructure',true,'schema',true,'version',1,'localMigrationEnabled',false,'gmailEnabled',false,'uploadsEnabled',false) $$;
REVOKE ALL ON FUNCTION public.foundation_health() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.foundation_health() TO anon,authenticated,service_role;
COMMENT ON FUNCTION public.foundation_health() IS 'Public status only; contains no rows, identity or credentials.';
COMMENT ON TABLE public.candidate_documents IS 'Metadata prepared; storage bucket and uploads intentionally not enabled pending cost confirmation.';
COMMENT ON TABLE public.employer_messages IS 'Gmail synchronization intentionally disabled; no body column.';